<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $money=static fn(float $value):string=>'R$ '.number_format($value,2,',','.'); ?>
<div class="actions"><div><span class="status">ADM · Financeiro</span><h1>Cursos e preços</h1><p class="meta">Defina o catálogo usado para gerar checkouts seguros no Asaas.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/admin/finance/products/create"><i class="fa-solid fa-plus" aria-hidden="true"></i> Novo curso</a></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<div class="table-responsive finance-customer-table"><table><thead><tr><th>Curso</th><th>Unidade</th><th>Formas</th><th>Valor</th><th>Validade</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php if($products===[]):?><tr><td colspan="7"><div class="finance-empty"><i class="fa-solid fa-book-open" aria-hidden="true"></i><strong>Nenhum curso cadastrado</strong><span>Cadastre o primeiro curso e seu preço para gerar checkouts.</span></div></td></tr><?php endif;?><?php foreach($products as$product):?><tr><td><strong><?= $escape($product['name']) ?></strong><?php if($product['description']):?><br><small><?= $escape($product['description']) ?></small><?php endif;?></td><td><?= $escape($product['unit_name']?:'Todas as unidades') ?></td><td><?= str_contains((string)$product['billing_types'],'PIX')?'Pix':'' ?><?= str_contains((string)$product['billing_types'],'CREDIT_CARD')?(str_contains((string)$product['billing_types'],'PIX')?' + ':'').'Cartão':'' ?></td><td><strong><?= $escape($money((float)$product['value'])) ?></strong></td><td><?= (int)$product['minutes_to_expire']===1440?'24 horas':(int)$product['minutes_to_expire'].' min' ?></td><td><span class="connection-badge"><?= (int)$product['is_active']===1?'Ativo':'Inativo' ?></span></td><td><a href="<?= $escape($basePath) ?>/admin/finance/products/<?= (int)$product['id'] ?>/edit">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
